/* Local moment book and replies. Other important-time collections remain separate. */
(() => {
 const UI=window.PrototypeUI,R=window.PrototypeRecords,KEY='dujia-prototype-moments',page=location.pathname.split('/').pop().slice(0,7),id=new URLSearchParams(location.search).get('id'),screen=document.querySelector('.screen');
 const all=()=>{const v=UI.read(KEY,[]);return Array.isArray(v)?v:[];},find=value=>all().find(v=>v.id===value),route=item=>'m04-p03.html?id='+encodeURIComponent(item.id);
 function put(item){const values=all(),index=values.findIndex(v=>v.id===item.id);if(index<0)values.unshift(item);else values[index]=item;return UI.write(KEY,values);}
 const visible=()=>all().filter(v=>PrototypePreferences.canView('moment',v));let refreshScope=()=>{};const home=()=>visible().length?'m04-p01.html':'m04-p02.html',nickname=()=>UI.read('dujia-profile',{}).nickname||'小满';
 const replies=()=>[...PrototypePreferences.sharedRecords().flatMap(r=>(r.comments||[]).map(c=>({comment:c,record:r,kind:'record',url:R.route(r)}))),...PrototypePreferences.sharedMoments().flatMap(r=>(r.comments||[]).map(c=>({comment:c,record:r,kind:'moment',url:route(r)})))].sort((a,b)=>b.comment.createdAt-a.comment.createdAt);
 document.querySelector('.back')?.addEventListener('click',()=>UI.back(page==='m04-p04'&&id&&find(id)?route(find(id)):home()));
 function missing(blocked=false){screen.classList.add('prototype-moment-missing');const box=blocked?UI.components.state({kind:'error',title:'这个时刻暂不可见',message:'来源当前不可共同使用，返回时刻册可以继续浏览自己的内容。',action:'返回时刻册',onAction:()=>UI.go(home())}):UI.collectionState(KEY,{title:'这个时刻已经不在了',action:'返回时刻册',fallback:home});box.classList.add('prototype-moment-state');screen.append(box);}
 function links(){const choices=[['纪念日',()=>UI.go(UI.read('dujia-prototype-anniversaries',[]).length?'m04-p07.html':'m04-p08.html')],['时光胶囊',()=>UI.go('m04-p12.html')],['悄悄留言',()=>UI.go(replies().length?'m04-p16.html':'m04-p17.html')]];let nav=document.querySelector('.links');if(!nav){nav=document.createElement('nav');nav.className='prototype-moment-links';nav.setAttribute('aria-label','其他重要时刻');screen.append(nav);for(const [name]of choices){const b=document.createElement('button');b.textContent=name;nav.append(b);}}[...nav.querySelectorAll('button')].forEach((b,i)=>b.onclick=choices[i][1]);const reminder=UI.components.button('共同提醒',()=>UI.go('m04-p05.html'),{variant:'secondary'});reminder.classList.add('prototype-moment-reminders');screen.after(reminder);}
 if(page==='m04-p01'||page==='m04-p02'){
  if((page==='m04-p01'&&!visible().length)||(page==='m04-p02'&&visible().length)){UI.go(home(),{replace:true,force:true});return;}links();
  if(page==='m04-p02'){
   document.querySelector('#from-records').onclick=()=>UI.go('m04-p04.html?choose=1');document.querySelector('.buttons button:not(#from-records)').onclick=()=>UI.go('m04-p04.html');
  }else{
   const cards=document.querySelector('.cards');cards.classList.add('prototype-moment-cards');let expanded=false;
   function paint(){cards.replaceChildren();for(const item of visible().slice(0,expanded?undefined:2)){const button=document.createElement('button'),title=document.createElement('b'),date=document.createElement('span');title.textContent=item.name;date.textContent=item.date;button.append(title,date);button.onclick=()=>UI.go(route(item));cards.append(button);}}
   paint();document.querySelector('#see-all').onclick=()=>{expanded=!expanded;document.querySelector('#see-all').textContent=expanded?'收起章节':'查看全部 ›';paint();};
   document.querySelector('.calendar').onclick=()=>UI.go(UI.read('dujia-prototype-anniversaries',[]).length?'m04-p07.html':'m04-p08.html');
   const next=visible().filter(v=>new Date(v.date+'T00:00:00')>=new Date(new Date().toDateString())).sort((a,b)=>a.date.localeCompare(b.date))[0];document.querySelector('.next').textContent=next?.name||'珍藏一个新时刻';document.querySelector('.next').onclick=()=>UI.go(next?route(next):'m04-p04.html');document.querySelector('.countdown').textContent=next?'还有 '+Math.max(0,Math.ceil((new Date(next.date+'T00:00:00')-Date.now())/86400000))+' 天':'把今天写进时刻册';
   const add=document.createElement('button');add.className='prototype-moment-create';add.textContent='＋';add.setAttribute('aria-label','新建重要时刻');add.onclick=()=>UI.go('m04-p04.html');screen.append(add);
   const refresh=document.createElement('button');refresh.className='prototype-moment-refresh';refresh.textContent='↻';refresh.setAttribute('aria-label','刷新时刻册');screen.append(refresh);let loading=false;
   async function load(){if(loading)return;loading=true;refresh.disabled=true;document.querySelector('#see-all').disabled=true;cards.replaceChildren();cards.setAttribute('aria-busy','true');cards.append(UI.components.loading({mode:'skeleton',label:'正在打开时刻册…'}));await new Promise(resolve=>setTimeout(resolve,400));loading=false;refresh.disabled=false;document.querySelector('#see-all').disabled=false;cards.removeAttribute('aria-busy');if(UI.failNext('moment-load')){cards.replaceChildren();const box=document.createElement('div');box.className='prototype-moment-error';const title=document.createElement('h2');title.textContent='时刻册暂时打不开';const retry=document.createElement('button');retry.textContent='重试加载时刻册';retry.onclick=load;box.append(title,retry);cards.append(box);}else paint();}refresh.onclick=load;load();
  }
 }
 if(page==='m04-p04'){
  const form=document.querySelector('#moment-form'),existing=id?find(id):null;if(id&&!existing){missing();return;}if(existing&&!PrototypePreferences.canView('moment',existing)){missing(true);return;}
  let cover=existing?.cover||null,selected=[...(existing?.related||[])],reading=false;
  form.elements.name.value=existing?.name||'';form.elements.date.value=existing?.date||new Date().toLocaleDateString('en-CA');form.elements.story.value=existing?.story||'';if(existing)form.elements.type.value=existing.type;
  const counter=document.querySelector('#counter'),image=document.querySelector('#cover-preview'),label=document.querySelector('#cover-label'),file=document.querySelector('#cover-file');
  function paint(){counter.textContent=form.elements.story.value.length+'/200';image.style.display=cover?'block':'none';if(cover)image.src=cover;label.style.display=cover?'none':'block';document.querySelector('#related').setAttribute('aria-label','关联共同记录，已选 '+selected.length+' 条');}
  paint();const leave=UI.guard(form,{fallback:existing?route(existing):home(),value:()=>JSON.stringify({name:form.elements.name.value,date:form.elements.date.value,type:form.elements.type.value,story:form.elements.story.value,cover,selected})});form.elements.story.addEventListener('input',paint);
  document.querySelector('#cover-button').onclick=()=>file.click();file.addEventListener('change',async()=>{if(!file.files[0])return;reading=true;try{cover=await R.readImage(file.files[0],'moment-image');paint();}catch(e){UI.toast(e.message+'，原封面仍保留','error');file.value='';}finally{reading=false;}});
  form.elements.date.readOnly=true;form.elements.date.onclick=async()=>{const input=document.createElement('input');input.type='date';input.value=form.elements.date.value;input.setAttribute('aria-label','选择发生日期');const action=await UI.sheet({title:'发生日期',content:input,actions:[{label:'使用这个日期',value:'apply'}]});if(action==='apply'&&input.value)form.elements.date.value=input.value;};
  async function choose(){const box=document.createElement('div'),records=R.all().filter(v=>v.visibility==='shared'&&v.status!=='draft');if(!records.length){box.textContent='还没有共同记录，可以先写日记或添加照片。';const create=await UI.modal({title:'选择共同记录',content:box,confirm:'去写日记',cancel:'继续创建时刻'});if(create)UI.go('m03-p05.html');return;}for(const record of records){const row=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.value=record.id;input.checked=selected.includes(record.id);row.className='prototype-record-choice';row.append(input,document.createTextNode(record.title));box.append(row);}const result=await UI.sheet({title:'关联共同记录',content:box,actions:[{label:'关联这些记录',value:'apply'}]});if(result==='apply'){selected=[...box.querySelectorAll('input:checked')].map(v=>v.value);paint();}}
  document.querySelector('#related').onclick=choose;if(new URLSearchParams(location.search).has('choose'))choose();
  form.addEventListener('submit',event=>{event.preventDefault();if(reading){UI.toast('封面正在读取，请稍候');return;}const name=form.elements.name.value.trim(),date=form.elements.date.value;if(!name||!/^\d{4}-\d{2}-\d{2}$/.test(date)){const field=!name?form.elements.name:form.elements.date;UI.fieldError(field,!name?'请填写时刻名称':'请选择有效日期');field.focus();return;}UI.busy(form.querySelector('.submit'),'保存中…',()=>{if(UI.failNext('moment-save'))throw new Error('重要时刻没有保存成功，请重试');const current=existing?UI.currentItem(KEY,existing):null;if(existing&&!current)return false;if(current&&!PrototypePreferences.canView('moment',current))throw new Error('这个时刻暂不可见，当前输入仍保留');const item={...current,id:existing?.id||'moment-'+crypto.randomUUID(),name,date,type:form.elements.type.value,story:form.elements.story.value.trim(),cover,related:selected.filter(id=>R.find(id)?.visibility==='shared'),createdAt:current?.createdAt||Date.now(),updatedAt:Date.now(),comments:current?.comments||[]};if(!put(item))return false;leave.commit();return UI.go(existing?route(item):home(),{force:true});});});form.dataset.prototypeReady='true';
 }
 if(page==='m04-p03'){
  let item=find(id||'sample-moment-1');if(!item){missing();return;}if(!PrototypePreferences.canView('moment',item)){missing(true);return;}
  document.querySelector('.moment-title').textContent=item.name;document.querySelector('.date').textContent=item.date;document.querySelector('.description').textContent=item.story;document.querySelector('.description').tabIndex=0;
  document.querySelector('.people span').textContent=nickname();document.querySelector('.people span:last-child').textContent=UI.read('dujia-prototype-relationship')?.partner||'阿舟';
  const cover=document.createElement('div');cover.className='prototype-moment-cover';if(item.cover){const img=document.createElement('img');img.src=item.cover;img.alt=item.name+'封面';cover.append(img);}else cover.textContent='这一页暂未添加封面';screen.append(cover);
  const related=document.querySelector('.related');related.classList.add('prototype-moment-related');related.replaceChildren();const sources=(item.related||[]).map(v=>R.find(v)).filter(v=>v&&PrototypePreferences.sharedContent('record',v));if(!sources.length)related.textContent='还没有关联记录';for(const record of sources){const b=document.createElement('button');b.textContent=record.title;b.onclick=()=>UI.go(R.route(record));related.append(b);}
  const edit=document.createElement('button');edit.className='prototype-moment-edit';edit.textContent='编辑';edit.setAttribute('aria-label','编辑时刻');edit.onclick=()=>UI.go('m04-p04.html?id='+encodeURIComponent(item.id));const more=document.createElement('button');more.id='more';more.className='prototype-moment-more';more.textContent='•••';more.setAttribute('aria-label','更多操作');screen.append(edit,more);
  more.onclick=async()=>{const action=await UI.sheet({title:'时刻操作',actions:[{label:'删除重要时刻',value:'delete',danger:true}]});if(action!=='delete'||!await UI.modal({title:'删除这个时刻？',message:'时刻及其中的留言将删除，关联的日记和照片仍保留。',confirm:'确认删除', danger: true,cancel:'取消'}))return;UI.busy(more,'删除中…',()=>{if(UI.failNext('moment-delete'))throw new Error('删除没有完成，请重试');if(!UI.write(KEY,all().filter(v=>v.id!==item.id)))return false;return UI.go(home(),{force:true});});};
  const message=document.querySelector('.message');function count(){message.textContent='悄悄留言 '+(item.comments||[]).length+' 条';}count();
  message.onclick=()=>{if(!PrototypePreferences.sharedContent('moment',find(item.id))){UI.toast('这个时刻不再共同可见','error');return;}const box=document.createElement('div');for(const comment of item.comments||[]){const p=document.createElement('p');p.textContent=comment.author+'：'+comment.text;box.append(p);}const form=document.createElement('form'),input=document.createElement('textarea'),button=document.createElement('button');form.className='prototype-moment-reply-form';input.maxLength=300;input.setAttribute('aria-label','回应这个时刻');button.type='submit';button.textContent='发送回应';if(window.PrototypePreferences?.privacy().replies===false){input.disabled=true;button.disabled=true;input.placeholder='新的回应已关闭';}form.append(input,button);box.append(form);const replyLeave=UI.protectSheet(form);form.addEventListener('submit',event=>{event.preventDefault();if(window.PrototypePreferences?.privacy().replies===false){UI.toast('新的回应已关闭');return;}const text=input.value.trim();if(!text){UI.fieldError(input,'请先写一句回应');input.focus();return;}UI.busy(button,'发送中…',async()=>{if(UI.failNext('moment-comment'))throw new Error('回应没有发送成功，请重试');const latest=find(item.id);if(!latest){UI.toast('这个时刻已删除','error');return false;}if(!PrototypePreferences.sharedContent('moment',latest)){UI.toast('这个时刻不再共同可见，未发送回应保留','error');return false;}const next={...latest,comments:[...(latest.comments||[]),{id:crypto.randomUUID(),text,author:nickname(),createdAt:Date.now(),read:false}]};if(!put(next))return false;item=next;count();replyLeave.commit();await UI.back();return true;});});UI.sheet({title:'时刻回应',content:box,actions:[],beforeClose:replyLeave.beforeClose});};
  refreshScope=()=>{const current=find(item.id),shared=current&&PrototypePreferences.sharedContent('moment',current);for(const form of document.querySelectorAll('.prototype-moment-reply-form')){form.querySelector('[type=submit]').disabled=!shared||PrototypePreferences.privacy().replies===false;form.parentElement.querySelectorAll(':scope > p').forEach(p=>p.hidden=!shared);}if(!current||!PrototypePreferences.canView('moment',current)){missing(!!current);return;}item=current;if(shared){document.querySelector('.people').innerHTML='<span></span><span></span>';document.querySelector('.people span').textContent=nickname();document.querySelector('.people span:last-child').textContent=UI.read('dujia-prototype-relationship')?.partner||'阿舟';message.disabled=false;count();}else{const people=document.querySelector('.people'),label=document.createElement('span');label.textContent='仅自己可见';label.style.gridColumn='1 / -1';people.replaceChildren(label);people.setAttribute('aria-label','可见范围');message.disabled=true;message.textContent='仅自己可见';}};refreshScope();
 }
 if(page==='m04-p16'||page==='m04-p17'){
  const values=replies();if((page==='m04-p16'&&!values.length)||(page==='m04-p17'&&values.length)){UI.go(values.length?'m04-p16.html':'m04-p17.html',{replace:true,force:true});return;}
  if(page==='m04-p17')document.querySelector('.go').onclick=()=>UI.go('m03-p06.html');
  else{document.querySelectorAll('.group-title').forEach(v=>v.remove());const cards=document.querySelector('.cards');cards.classList.add('prototype-reply-cards');cards.replaceChildren();for(const entry of values){const article=document.createElement('article'),source=document.createElement('b'),body=document.createElement('p'),button=document.createElement('button');source.textContent=entry.record.name||entry.record.title;body.textContent=entry.comment.author+'：'+entry.comment.text;button.textContent='查看原记录'+(entry.comment.read?' · 已读':'');button.onclick=()=>{const current=entry.kind==='moment'?find(entry.record.id):R.find(entry.record.id);if(!current||!PrototypePreferences.sharedContent(entry.kind==='moment'?'moment':'record',current)){UI.toast('原内容不再共同可见，请刷新留言列表','error');return;}if(!(current.comments||[]).some(v=>v.id===entry.comment.id)){UI.toast('这条留言已不存在，请刷新留言列表','error');return;}const record={...current,comments:(current.comments||[]).map(v=>v.id===entry.comment.id?{...v,read:true}:v)};if(!(entry.kind==='moment'?put(record):R.put(record)))return;UI.go(entry.kind==='moment'?route(record):R.route(record));};article.append(source,body,button);cards.append(article);}}
 }
 addEventListener('storage',event=>{if(![KEY,'dujia-prototype-records','dujia-prototype-capsules','dujia-prototype-works','dujia-profile'].includes(event.key))return;if(page==='m04-p04'||document.querySelector('dialog[open]')){refreshScope();UI.toast('内容已更新，当前输入保留；提交时核对最新范围');return;}location.reload();});
})();
